package com.newsvoice.tts;

import android.content.Context;
import android.graphics.*;
import android.media.*;
import android.speech.tts.*;
import android.text.*;
import android.view.Surface;
import java.io.*;
import java.nio.*;
import java.nio.file.*;
import java.util.*;
import java.util.concurrent.*;

public final class RadioVideo {
    public record Cue(long start,long end,String text){}
    public interface Progress {void update(String message);}
    public static final int WIDTH=360,HEIGHT=640,FPS=12,RATE=24000,AUDIO_BITRATE=48000;
    private static final long LIMIT=5_000_000,US=1_000_000;
    private static long us(long samples){return samples*US/RATE;}
    private RadioVideo(){}
    public static File fromText(Context context,List<String> sentences,String voice,float speed,File dest,Progress progress)throws Exception{
        if(sentences.isEmpty())throw new IOException("Empty text");File dir=work(context);TextToSpeech engine=null;
        try{
            CountDownLatch init=new CountDownLatch(1);int[] state={TextToSpeech.ERROR};engine=new TextToSpeech(context,s->{state[0]=s;init.countDown();});
            if(!init.await(30,TimeUnit.SECONDS)||state[0]!=TextToSpeech.SUCCESS)throw new IOException("음성 엔진 초기화 실패");
            if(engine.setLanguage(Locale.KOREA)<0)throw new IOException("한국어 음성 엔진이 없습니다");
            Voice chosen=null;if(engine.getVoices()!=null)for(Voice v:engine.getVoices())if("ko".equals(v.getLocale().getLanguage())&&!v.isNetworkConnectionRequired()&&(chosen==null||v.getName().equals(voice))){chosen=v;if(v.getName().equals(voice))break;}
            if(chosen==null)throw new IOException("한국어 오프라인 음성을 설치하세요");engine.setVoice(chosen);engine.setSpeechRate(speed);
            ArrayBlockingQueue<String> done=new ArrayBlockingQueue<>(2);engine.setOnUtteranceProgressListener(new UtteranceProgressListener(){public void onStart(String id){}public void onDone(String id){done.offer(id);}public void onError(String id){done.offer("error:"+id);}});
            File pcm=new File(dir,"broadcast.pcm");List<Cue> cues=new ArrayList<>();long samples=0;
            try(OutputStream out=new BufferedOutputStream(new FileOutputStream(pcm))){samples+=wavToPcm(OpeningMusicA.ensureInstalled(context),out);for(int i=0;i<sentences.size();i++){
                progress.update("음성 제작 "+(i+1)+" / "+sentences.size());File wave=new File(dir,"part.wav");String id="p"+i;
                if(engine.synthesizeToFile(sentences.get(i),new android.os.Bundle(),wave,id)!=TextToSpeech.SUCCESS||!id.equals(done.poll(90,TimeUnit.SECONDS)))throw new IOException("음성 제작 실패: "+(i+1));
                long start=samples;samples+=wavToPcm(wave,out);cues.add(new Cue(us(start)/1000,us(samples)/1000,sentences.get(i)));wave.delete();
            }}
            finish(dir,pcm,cues,dest,progress);return dest;
        }finally{if(engine!=null)engine.shutdown();clean(dir);}
    }
    public static File fromMp3(Context context,File input,List<Cue> captions,File dest,Progress progress)throws Exception{
        File dir=work(context);try{File pcm=new File(dir,"broadcast.pcm");progress.update("음성 변환 중");decode(input,pcm);finish(dir,pcm,captions,dest,progress);return dest;}finally{clean(dir);}
    }
    public static File fromPcm(Context context,File pcm,List<Cue> captions,File dest,Progress progress)throws Exception{File dir=work(context);try{finish(dir,pcm,captions,dest,progress);return dest;}finally{clean(dir);}}
    private static File work(Context c)throws IOException{File dir=new File(c.getCacheDir(),"radio42-"+UUID.randomUUID());if(!dir.mkdir())throw new IOException("Cannot create temp folder");return dir;}
    private static void clean(File dir){File[] list=dir.listFiles();if(list!=null)for(File f:list)f.delete();dir.delete();}
    private static int le16(byte[] a,int i){return (a[i]&255)|((a[i+1]&255)<<8);}private static int le32(byte[] a,int i){return le16(a,i)|(le16(a,i+2)<<16);}
    private static long wavToPcm(File wav,OutputStream out)throws IOException{WavTools.Piece p=WavTools.inspect(wav);int channels=le16(p.format,2),rate=le32(p.format,4),bits=le16(p.format,14);if(le16(p.format,0)!=1||bits!=16||channels<1||channels>8||rate<=0)throw new IOException("Unsupported PCM WAV format");Resampler r=new Resampler(rate,channels,out);try(RandomAccessFile file=new RandomAccessFile(p.file,"r")){file.seek(p.dataOffset);int step=channels*2;byte[] b=new byte[16384/step*step];long left=p.dataLength;while(left>0){int n=(int)Math.min(left,b.length);file.readFully(b,0,n);r.write(ByteBuffer.wrap(b,0,n).order(ByteOrder.LITTLE_ENDIAN));left-=n;}}return r.output;}
    private static final class Resampler {final int inRate,channels;final OutputStream out;long input,output;Resampler(int r,int c,OutputStream o){inRate=r;channels=c;out=o;}void write(ByteBuffer b)throws IOException{b.order(ByteOrder.LITTLE_ENDIAN);while(b.remaining()>=channels*2){int sum=0;for(int c=0;c<channels;c++)sum+=b.getShort();int s=sum/channels;input++;while(output*inRate<input*RATE){out.write(s&255);out.write((s>>8)&255);output++;}}}}
    private static void decode(File input,File pcm)throws Exception{
        MediaExtractor x=new MediaExtractor();MediaCodec codec=null;try(OutputStream out=new BufferedOutputStream(new FileOutputStream(pcm))){x.setDataSource(input.getAbsolutePath());int track=-1;for(int i=0;i<x.getTrackCount();i++)if(x.getTrackFormat(i).getString(MediaFormat.KEY_MIME).startsWith("audio/")){track=i;break;}if(track<0)throw new IOException("No audio track");MediaFormat f=x.getTrackFormat(track);x.selectTrack(track);f.setInteger(MediaFormat.KEY_PCM_ENCODING,AudioFormat.ENCODING_PCM_16BIT);codec=MediaCodec.createDecoderByType(f.getString(MediaFormat.KEY_MIME));codec.configure(f,null,null,0);codec.start();MediaCodec.BufferInfo info=new MediaCodec.BufferInfo();boolean inDone=false,outDone=false;Resampler resampler=null;int idle=0;
            while(!outDone){if(!inDone){int i=codec.dequeueInputBuffer(10000);if(i>=0){ByteBuffer b=codec.getInputBuffer(i);b.clear();int n=x.readSampleData(b,0);if(n<0){codec.queueInputBuffer(i,0,0,0,MediaCodec.BUFFER_FLAG_END_OF_STREAM);inDone=true;}else{codec.queueInputBuffer(i,0,n,x.getSampleTime(),0);x.advance();}}}int i=codec.dequeueOutputBuffer(info,10000);if(i==MediaCodec.INFO_OUTPUT_FORMAT_CHANGED){MediaFormat o=codec.getOutputFormat();if(o.containsKey(MediaFormat.KEY_PCM_ENCODING)&&o.getInteger(MediaFormat.KEY_PCM_ENCODING)!=AudioFormat.ENCODING_PCM_16BIT)throw new IOException("Unsupported audio PCM encoding");resampler=new Resampler(o.getInteger(MediaFormat.KEY_SAMPLE_RATE),o.getInteger(MediaFormat.KEY_CHANNEL_COUNT),out);idle=0;}else if(i>=0){ByteBuffer b=codec.getOutputBuffer(i);if(info.size>0){if(resampler==null){MediaFormat o=codec.getOutputFormat();resampler=new Resampler(o.getInteger(MediaFormat.KEY_SAMPLE_RATE),o.getInteger(MediaFormat.KEY_CHANNEL_COUNT),out);}b.position(info.offset);b.limit(info.offset+info.size);resampler.write(b);}outDone=(info.flags&MediaCodec.BUFFER_FLAG_END_OF_STREAM)!=0;codec.releaseOutputBuffer(i,false);idle=0;}else if(++idle>500)throw new IOException("Audio decoder stalled");}
        }finally{x.release();if(codec!=null){try{codec.stop();}catch(Exception ignored){}codec.release();}}
    }
    private static void finish(File dir,File pcm,List<Cue> captions,File dest,Progress progress)throws Exception{
        long duration=us(pcm.length()/2);if(duration<=0||captions.isEmpty())throw new IOException("Audio and captions required");File aac=new File(dir,"audio.m4a"),video=new File(dir,"video.mp4"),joined=new File(dir,"final.mp4");progress.update("AAC 음성 압축 중");encodeAudio(pcm,aac);long budget=Math.max(100000,LIMIT*duration/(300*US));boolean ok=false;
        for(int bitrate:new int[]{65000,48000,32000}){if(video.exists())video.delete();if(joined.exists())joined.delete();encodeVideo(video,captions,duration,bitrate,progress);join(video,aac,joined);if(joined.length()<=budget){ok=true;break;}progress.update("파일 용량 조정 중");}
        if(!ok)throw new IOException("5분당 5MB 목표를 충족하지 못했습니다");Files.move(joined.toPath(),dest.toPath(),StandardCopyOption.REPLACE_EXISTING);Files.copy(aac.toPath(),new File(dest.getParentFile(),"broadcast.m4a").toPath(),StandardCopyOption.REPLACE_EXISTING);progress.update("제작 완료");
    }
    private static void encodeAudio(File pcm,File output)throws Exception{
        MediaCodec codec=MediaCodec.createEncoderByType(MediaFormat.MIMETYPE_AUDIO_AAC);MediaMuxer mux=null;boolean started=false;try(InputStream in=new BufferedInputStream(new FileInputStream(pcm))){MediaFormat f=MediaFormat.createAudioFormat(MediaFormat.MIMETYPE_AUDIO_AAC,RATE,1);f.setInteger(MediaFormat.KEY_AAC_PROFILE,MediaCodecInfo.CodecProfileLevel.AACObjectLC);f.setInteger(MediaFormat.KEY_BIT_RATE,AUDIO_BITRATE);f.setInteger(MediaFormat.KEY_MAX_INPUT_SIZE,16384);codec.configure(f,null,null,MediaCodec.CONFIGURE_FLAG_ENCODE);codec.start();mux=new MediaMuxer(output.getAbsolutePath(),MediaMuxer.OutputFormat.MUXER_OUTPUT_MPEG_4);MediaCodec.BufferInfo info=new MediaCodec.BufferInfo();byte[] buf=new byte[16384];long sent=0;int track=-1,idle=0;boolean inDone=false,outDone=false;while(!outDone){if(!inDone){int i=codec.dequeueInputBuffer(10000);if(i>=0){ByteBuffer b=codec.getInputBuffer(i);b.clear();int max=Math.min(b.remaining(),buf.length)&~1;int n=0;while(n<max){int k=in.read(buf,n,max-n);if(k<0)break;n+=k;}if(n==0){codec.queueInputBuffer(i,0,0,us(sent),MediaCodec.BUFFER_FLAG_END_OF_STREAM);inDone=true;}else{b.put(buf,0,n);codec.queueInputBuffer(i,0,n,us(sent),0);sent+=n/2;}}}int i=codec.dequeueOutputBuffer(info,10000);if(i==MediaCodec.INFO_OUTPUT_FORMAT_CHANGED){track=mux.addTrack(codec.getOutputFormat());mux.start();started=true;idle=0;}else if(i>=0){ByteBuffer b=codec.getOutputBuffer(i);if(info.size>0&&(info.flags&MediaCodec.BUFFER_FLAG_CODEC_CONFIG)==0){b.position(info.offset);b.limit(info.offset+info.size);mux.writeSampleData(track,b,info);}outDone=(info.flags&MediaCodec.BUFFER_FLAG_END_OF_STREAM)!=0;codec.releaseOutputBuffer(i,false);idle=0;}else if(++idle>500)throw new IOException("AAC encoder stalled");}}finally{try{codec.stop();}catch(Exception ignored){}codec.release();if(mux!=null){if(started)mux.stop();mux.release();}}}
    private static void encodeVideo(File output,List<Cue> cues,long duration,int bitRate,Progress progress)throws Exception{
        MediaCodec codec=MediaCodec.createEncoderByType(MediaFormat.MIMETYPE_VIDEO_AVC);MediaMuxer mux=null;boolean started=false;Surface surface=null;Bitmap bitmap=Bitmap.createBitmap(WIDTH,HEIGHT,Bitmap.Config.ARGB_8888);try{MediaFormat f=MediaFormat.createVideoFormat(MediaFormat.MIMETYPE_VIDEO_AVC,WIDTH,HEIGHT);f.setInteger(MediaFormat.KEY_COLOR_FORMAT,MediaCodecInfo.CodecCapabilities.COLOR_FormatSurface);f.setInteger(MediaFormat.KEY_BIT_RATE,bitRate);f.setInteger(MediaFormat.KEY_FRAME_RATE,FPS);f.setInteger(MediaFormat.KEY_I_FRAME_INTERVAL,4);f.setInteger(MediaFormat.KEY_MAX_B_FRAMES,0);if(codec.getCodecInfo().getCapabilitiesForType(MediaFormat.MIMETYPE_VIDEO_AVC).getEncoderCapabilities().isBitrateModeSupported(MediaCodecInfo.EncoderCapabilities.BITRATE_MODE_CBR))f.setInteger(MediaFormat.KEY_BITRATE_MODE,MediaCodecInfo.EncoderCapabilities.BITRATE_MODE_CBR);codec.configure(f,null,null,MediaCodec.CONFIGURE_FLAG_ENCODE);surface=codec.createInputSurface();codec.start();mux=new MediaMuxer(output.getAbsolutePath(),MediaMuxer.OutputFormat.MUXER_OUTPUT_MPEG_4);MediaCodec.BufferInfo info=new MediaCodec.BufferInfo();int track=-1;boolean eos=false;long frames=(duration*FPS+US-1)/US;TextPaint paint=new TextPaint(Paint.ANTI_ALIAS_FLAG);paint.setColor(Color.WHITE);paint.setTextSize(22);List<StaticLayout> layouts=new ArrayList<>();float[] tops=new float[cues.size()];float y=0;for(int i=0;i<cues.size();i++){tops[i]=y;StaticLayout l=StaticLayout.Builder.obtain(cues.get(i).text(),0,cues.get(i).text().length(),paint,WIDTH-28).setLineSpacing(5,1.05f).setIncludePad(false).build();layouts.add(l);y+=l.getHeight()+16;}Canvas canvas=new Canvas(bitmap);
            try(EglFrameRenderer gl=new EglFrameRenderer(surface,WIDTH,HEIGHT)){surface=null;int active=0;for(long frame=0;frame<frames;frame++){long time=frame*US/FPS;long at=time/1000-700;while(active+1<cues.size()&&at>=cues.get(active+1).start())active++;float offset=tops[active];if(active+1<cues.size()&&at>=cues.get(active).start()){long start=cues.get(active).start(),end=cues.get(active+1).start();float p=Math.max(0,Math.min(1,(at-start)/(float)Math.max(1,end-start)));offset+=p*(tops[active+1]-tops[active]);}canvas.drawColor(Color.BLACK);if(at>=cues.get(0).start()){for(int i=0;i<layouts.size();i++){float top=HEIGHT/3f+tops[i]-offset;StaticLayout l=layouts.get(i);if(top+l.getHeight()<0||top>HEIGHT)continue;canvas.save();canvas.translate(14,top);l.draw(canvas);canvas.restore();}}gl.upload(bitmap);gl.draw(time*1000,1f);while(true){int i=codec.dequeueOutputBuffer(info,0);if(i==MediaCodec.INFO_TRY_AGAIN_LATER)break;if(i==MediaCodec.INFO_OUTPUT_FORMAT_CHANGED){track=mux.addTrack(codec.getOutputFormat());mux.start();started=true;}else if(i>=0){writeVideo(codec,mux,track,info,i);}}if(frame%Math.max(1,frames/100)==0)progress.update("영상 제작 "+(frame*100/frames)+"%");}codec.signalEndOfInputStream();int idle=0;while(!eos){int i=codec.dequeueOutputBuffer(info,10000);if(i==MediaCodec.INFO_OUTPUT_FORMAT_CHANGED){track=mux.addTrack(codec.getOutputFormat());mux.start();started=true;idle=0;}else if(i>=0){eos=(info.flags&MediaCodec.BUFFER_FLAG_END_OF_STREAM)!=0;writeVideo(codec,mux,track,info,i);idle=0;}else if(++idle>500)throw new IOException("Video encoder stalled");}}
        }finally{if(surface!=null)surface.release();bitmap.recycle();try{codec.stop();}catch(Exception ignored){}codec.release();if(mux!=null){if(started)mux.stop();mux.release();}}}
    private static void writeVideo(MediaCodec codec,MediaMuxer mux,int track,MediaCodec.BufferInfo info,int index){ByteBuffer b=codec.getOutputBuffer(index);if(info.size>0&&(info.flags&MediaCodec.BUFFER_FLAG_CODEC_CONFIG)==0){b.position(info.offset);b.limit(info.offset+info.size);mux.writeSampleData(track,b,info);}codec.releaseOutputBuffer(index,false);}
    private static void join(File video,File audio,File dest)throws Exception{MediaExtractor v=new MediaExtractor(),a=new MediaExtractor();MediaMuxer mux=null;boolean started=false;try{v.setDataSource(video.getAbsolutePath());a.setDataSource(audio.getAbsolutePath());v.selectTrack(0);a.selectTrack(0);mux=new MediaMuxer(dest.getAbsolutePath(),MediaMuxer.OutputFormat.MUXER_OUTPUT_MPEG_4);int vt=mux.addTrack(v.getTrackFormat(0)),at=mux.addTrack(a.getTrackFormat(0));mux.start();started=true;ByteBuffer b=ByteBuffer.allocateDirect(1024*1024);MediaCodec.BufferInfo info=new MediaCodec.BufferInfo();while(v.getSampleTime()>=0||a.getSampleTime()>=0){boolean takeV=a.getSampleTime()<0||(v.getSampleTime()>=0&&v.getSampleTime()<=a.getSampleTime());MediaExtractor x=takeV?v:a;b.clear();int n=x.readSampleData(b,0);if(n<0)throw new IOException("Invalid media sample");info.set(0,n,x.getSampleTime(),x.getSampleFlags());b.position(0);b.limit(n);mux.writeSampleData(takeV?vt:at,b,info);x.advance();}}finally{v.release();a.release();if(mux!=null){if(started)mux.stop();mux.release();}}}
}
